# Fallback content when service config files are unavailable
_GATEWAY_SEED_FALLBACK: dict[str, str] = {
    "profiles.yaml": "profiles: {}\n",
    "model_transformations.yaml": "transformations: {}\n",
}

# ∀ file ∈ _GATEWAY_SEED_FALLBACK: if content == fallback, file was never populated
_SERVICE_CONFIG_DIR = WORKSPACE_ROOT / "services/universal-stargate/config"


def _gateway_seed_content(name: str) -> str:
    """Return seed content for a ~/.gateway config file.

    Reads from services/universal-stargate/config/ when available so that
    profiles and transformations ship with working defaults. Falls back to
    the empty-placeholder string if the source file is missing.
    """
    source = _SERVICE_CONFIG_DIR / name
    if source.exists():
        return source.read_text()
    fallback = _GATEWAY_SEED_FALLBACK.get(name, "")
    logger.warning("Service config not found: %s — using empty fallback", source)
    return fallback


def load_env_file(path: Path) -> dict[str, str]:
    """Parse KEY=VALUE lines from an env file. Shared for TUI and headless relay."""
    entries: dict[str, str] = {}
    if not path.exists():
        return entries
    try:
        lines = path.read_text().splitlines()
    except OSError as exc:
        logger.warning("Could not read env file %s: %s", path, exc)
        return entries
    for line in lines:
        line = line.strip()
        if line.startswith("export "):
            line = line[len("export ") :]
        if line and not line.startswith("#") and "=" in line:
            key, value = line.split("=", 1)
            key = key.strip()
            if key:
                entries[key] = os.path.expandvars(value.strip())
    return entries


def build_service_env(
    workspace_root: Path, node_env_path: Path | None = None
) -> dict[str, str]:
    """Build env dict from os.environ + .env.local + secrets.env + optional node env.

    Also backfills ``MCP_PUBLIC_URL`` and ``MCP_AUTH_TOKEN`` from
    ``~/.gateway/mcp.yaml`` when missing — required by the gateway/Stargate
    container for the frontier-dispatch ``remote_mcp`` code path
    (``libs/llm_adapters/_mcp_entry.resolve_mcp_env``). Both env vars must be
    set in the ``manage`` process environment for the compose passthrough in
    ``docker/compose/unix-socket.yml`` to populate the container.
    """
    env = dict(os.environ)
    env.update(load_env_file(workspace_root / ".env.local"))
    env.update(load_env_file(GATEWAY_DIR / "secrets.env"))
    # CURSOR_API_KEY_OTHER_MODELS — secondary Cursor API key for Other Models pool
    # dispatches via git-integration-worker (see cursor_sdk_context.resolve_cursor_api_key).
    if node_env_path:
        env.update(load_env_file(node_env_path))
    cfg = load_mcp_config()
    if cfg is not None:
        if not env.get("MCP_AUTH_TOKEN") and cfg.auth_token:
            env["MCP_AUTH_TOKEN"] = cfg.auth_token
        if not env.get("MCP_PUBLIC_URL") and cfg.mcp_server_url:
            env["MCP_PUBLIC_URL"] = cfg.mcp_server_url
    cortex_http = load_cortex_api_config()
    # Operator-owned bind — always mirror yaml so stale shell env cannot narrow it.
    env["CORTEX_API_HTTP_HOST"] = cortex_http.http_host
    env["CORTEX_API_HTTP_PORT"] = str(cortex_http.http_port)
    return env


def apply_checkout_code_version(
    env: dict[str, str], workspace_root: Path
) -> dict[str, str]:
    """Seal ``ULG_CODE_VERSION`` from checkout HEAD for edge compose passthrough.

    The gpu-edge container has no ``git`` binary and no ``.git`` mount; without
    this seal ``resolve_code_version()`` returns the ``unknown`` sentinel.

    Docker Compose interpolates an undefined ``${ULG_CODE_VERSION}`` to the empty
    string without warning, which still satisfies presence checks in the
    container. Callers must invoke this before ``docker compose up``; an empty or
    malformed host value is replaced, and failure to read checkout HEAD raises.
    """
    from deploy_identity.code_version import is_valid_sha40, read_checkout_head

    existing = env.get("ULG_CODE_VERSION", "").strip()
    if existing and is_valid_sha40(existing):
        env["ULG_CODE_VERSION"] = existing.lower()
        return env

    env.pop("ULG_CODE_VERSION", None)
    sha = read_checkout_head(workspace_root)
    if not sha or not is_valid_sha40(sha):
        msg = (
            f"Cannot seal ULG_CODE_VERSION from checkout HEAD at {workspace_root} "
            "(git unavailable or HEAD is not a 40-hex SHA)"
        )
        logger.error(msg)
        raise RuntimeError(msg)
    env["ULG_CODE_VERSION"] = sha.lower()
    return env


_MANAGE_TUI_LOG_DIR = Path("/tmp/logs/tui")


def bootstrap_manage_process_logging_env() -> None:
    """Set LOG_DIR before any ``universal_logging`` import in the manage TUI."""
    _MANAGE_TUI_LOG_DIR.mkdir(parents=True, exist_ok=True)
    os.environ.setdefault("LOG_DIR", str(_MANAGE_TUI_LOG_DIR))
    os.environ.setdefault("SERVICE_NAME", "manage_tui")
    os.environ.setdefault("TRUNCATE_LOGS", "true")


def apply_host_service_logging_env(
    env: dict[str, str],
    *,
    log_dir: Path | str,
    log_filename: str,
) -> None:
    """Wire ``universal_logging`` file handlers to the manage launcher log dir."""
    log_path = Path(log_dir)
    log_path.mkdir(parents=True, exist_ok=True)
    service_name = Path(log_filename).stem.replace("-", "_")
    env["LOG_DIR"] = str(log_path)
    env["SERVICE_NAME"] = service_name
    env["TRUNCATE_LOGS"] = "true"


