def ensure_cortex_api_config() -> Path:
    """Generate ~/.gateway/cortex-api.yaml template if absent."""
    GATEWAY_DIR.mkdir(parents=True, exist_ok=True)
    if not _CORTEX_API_CONFIG_PATH.exists():
        _CORTEX_API_CONFIG_PATH.write_text(_CORTEX_API_CONFIG_TEMPLATE)
        logger.info("Generated cortex-api config: %s", _CORTEX_API_CONFIG_PATH)
    return _CORTEX_API_CONFIG_PATH


def load_cortex_api_config() -> CortexApiConfig:
    """Load ~/.gateway/cortex-api.yaml; defaults when absent or invalid."""
    default = CortexApiConfig()
    if not _CORTEX_API_CONFIG_PATH.exists():
        return default
    try:
        raw = yaml.safe_load(_CORTEX_API_CONFIG_PATH.read_text(encoding="utf-8")) or {}
    except Exception:
        logger.error(
            "Failed to parse cortex-api config: %s",
            _CORTEX_API_CONFIG_PATH,
            exc_info=True,
        )
        return default
    if not isinstance(raw, dict):
        return default
    http = raw.get("http", {})
    if not isinstance(http, dict):
        http = {}
    host = str(http.get("host", default.http_host)).strip() or default.http_host
    try:
        port = int(http.get("port", default.http_port))
    except (TypeError, ValueError):
        port = default.http_port
    return CortexApiConfig(http_host=host, http_port=port)


def cortex_api_http_bind() -> tuple[str, int]:
    """Resolve Control Tower TCP bind from ~/.gateway/cortex-api.yaml only."""
    cfg = load_cortex_api_config()
    return cfg.http_host, cfg.http_port


def ensure_event_service_config() -> Path:
    """Generate ~/.gateway/event-service.yaml template if absent."""
    GATEWAY_DIR.mkdir(parents=True, exist_ok=True)
    if not _EVENT_SERVICE_CONFIG_PATH.exists():
        _EVENT_SERVICE_CONFIG_PATH.write_text(_EVENT_SERVICE_CONFIG_TEMPLATE)
        logger.info("Generated event-service config: %s", _EVENT_SERVICE_CONFIG_PATH)
    return _EVENT_SERVICE_CONFIG_PATH


def load_event_service_config() -> EventServiceConfig | None:
    """Load ~/.gateway/event-service.yaml. Returns None if absent."""
    if not _EVENT_SERVICE_CONFIG_PATH.exists():
        return None
    try:
        raw = (
            yaml.safe_load(_EVENT_SERVICE_CONFIG_PATH.read_text(encoding="utf-8")) or {}
        )
    except Exception:
        logger.error(
            "Failed to parse event-service config: %s",
            _EVENT_SERVICE_CONFIG_PATH,
            exc_info=True,
        )
        return None
    if not isinstance(raw, dict):
        return None
    tcp = raw.get("tcp", {})
    if not isinstance(tcp, dict):
        tcp = {}
    retention = raw.get("retention", {})
    if not isinstance(retention, dict):
        retention = {}
    return EventServiceConfig(
        tcp_enabled=_parse_bool(tcp.get("enabled"), default=False),
        tcp_host=str(tcp.get("host", "127.0.0.1")).strip() or "127.0.0.1",
        tcp_ingest_port=int(tcp.get("ingest_port", 7101)),
        tcp_query_port=int(tcp.get("query_port", 7102)),
        retention_days=int(retention.get("days", 2)),
        max_sessions=int(retention.get("max_sessions", 2)),
    )


